function getOrCreateKot(PDO $pdo, int $blokId, string $ad): ?int {
    if (!$ad) return null;
    $ad = trim($ad);
    $s = $pdo->prepare("SELECT id FROM kotlar WHERE blok_id = ? AND kot_degeri = ?");
    $s->execute([$blokId, $ad]);
    $id = $s->fetchColumn();
    if ($id) return (int)$id;
    $pdo->prepare("INSERT INTO kotlar (blok_id, kot_degeri) VALUES (?, ?)")->execute([$blokId, $ad]);
    return (int)$pdo->lastInsertId();
}

$result = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['import'])) {
    $added = 0; $skipped = 0; $errors = [];

    foreach ($excelRows as $r) {
        try {
            $tarih = $r['tarih'] ?? null; // already YYYY-MM-DD
            if (!$tarih) { $skipped++; continue; }

            $tedarikciId = getOrCreate($pdo, 'tedarikciler', 'ad', trim($r['tedarikci'] ?? ''));
            if (!$tedarikciId) { $skipped++; continue; }

            $betonId    = $r['beton_sinifi'] ? getOrCreate($pdo, 'beton_siniflari', 'ad', trim($r['beton_sinifi'])) : null;
            $pompaId    = $r['pompa']        ? getOrCreate($pdo, 'pompa_turleri',   'ad', trim($r['pompa']))        : null;
            $katki1Id   = $r['katki1']       ? getOrCreate($pdo, 'katki_listesi',   'ad', trim($r['katki1']))       : null;
            $katki2Id   = $r['katki2']       ? getOrCreate($pdo, 'katki_listesi',   'ad', trim($r['katki2']))       : null;
            $firmaId    = $r['firma']        ? getOrCreate($pdo, 'firmalar',        'ad', trim($r['firma']))        : null;
            $kivamId    = $r['kivam_sinifi'] ? getOrCreate($pdo, 'kivam_siniflari', 'ad', trim($r['kivam_sinifi'])) : null;

            $imalatGrupId = $r['imalat_grup']   ? getOrCreateImalat($pdo, trim($r['imalat_grup']))                              : null;
            $anaKalemId   = ($imalatGrupId && $r['ana_is_kalemi']) ? getOrCreateAnaKalem($pdo, $imalatGrupId, trim($r['ana_is_kalemi'])) : null;
            $parselId     = $r['parsel'] ? getOrCreateParsel($pdo, trim($r['parsel'])) : null;
            $blokId       = ($parselId && $r['blok']) ? getOrCreateBlok($pdo, $parselId, trim($r['blok'])) : null;
            $kotId        = ($blokId && $r['kot'])    ? getOrCreateKot($pdo, $blokId, trim($r['kot']))     : null;

            $projeId = $r['parsel'] ? parselToProjeId(trim($r['parsel']), $projeMap) : ($projeMap['U030'] ?? null);

            // Duplicate kontrol
            if ($r['irsaliye_no']) {
                $dup = $pdo->prepare("SELECT COUNT(*) FROM irsaliyeler WHERE irsaliye_no = ?");
                $dup->execute([$r['irsaliye_no']]);
                if ($dup->fetchColumn() > 0) { $skipped++; continue; }
            }

            $mikserCikis = (!empty($r['mikser_cikis']) && $r['mikser_cikis'] !== '00:00:00') ? $r['mikser_cikis'] : null;
            $kantarGiris = (!empty($r['kantar_giris']) && $r['kantar_giris'] !== '00:00:00') ? $r['kantar_giris'] : null;
            $kantarCikis = (!empty($r['kantar_cikis']) && $r['kantar_cikis'] !== '00:00:00') ? $r['kantar_cikis'] : null;

            $pdo->prepare("INSERT INTO irsaliyeler
                (tip, sira_no, fatura_no, arac_plaka, kivam_sinifi_id, irsaliye_no,
                 proje_id, tedarikci_id, tarih,
                 mikser_cikis_saati, kantar_giris_saati, kantar_cikis_saati,
                 kantar_net_yildizlar, kantar_net_tedarikci, kantar_farki,
                 beton_sinifi_id, miktar, birim, pompa_id,
                 katki1_id, katki2_id, firma_id,
                 imalat_grup_id, ana_is_kalemi_id,
                 parsel_id, blok_id, kot_id, aciklama)
                VALUES ('alis',?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")
                ->execute([
                    $r['sira_no'], $r['fatura_no'], $r['arac_plaka'],
                    $kivamId, $r['irsaliye_no'],
                    $projeId, $tedarikciId, $tarih,
                    $mikserCikis, $kantarGiris, $kantarCikis,
                    $r['kantar_net_yildiz'], $r['kantar_net_tedarikci'], $r['kantar_farki'],
                    $betonId, $r['miktar'], 'M3', $pompaId,
                    $katki1Id, $katki2Id, $firmaId,
                    $imalatGrupId, $anaKalemId,
                    $parselId, $blokId, $kotId, $r['aciklama'],
                ]);
            $added++;
        } catch (PDOException $e) {
            $errors[] = "Sıra {$r['sira_no']} ({$r['irsaliye_no']}): " . h($e->getMessage());
            $skipped++;
        }
    }
    $result = compact('added', 'skipped', 'errors');
}

